mapper.select:
select p.* from tb_screen_person p left join tb_screen_sum c on p.id=c.person_id

    name like concat('%',#{name},'%')
    and   id_num like concat('%',#{idNum},'%')
    and   screen_id =#{screenId}
    and   p.screen_type =#{screenType}

        and
        (

            first_type IN(

                #{type}

            )

           or
        more_type & #{moreTypeNum}  > 0
           )

    and ( c.last_chest_radiograph_time BETWEEN #{startTime}  AND #{endTime})

   order by id desc
limit #{pageNo},#{pageSize};

select count(DISTINCT p.id) from tb_screen_person p left join tb_screen_sum c on p.id=c.person_id

    name like concat('%',#{name},'%')
    and   id_num like concat('%',#{idNum},'%')
    and   screen_id =#{screenId}
    and   p.screen_type =#{screenType}

        and
        (

            first_type IN(

                #{type}
            )

        or
        more_type & #{moreTypeNum}  > 0
        )

    and ( c.last_chest_radiograph_time BETWEEN #{startTime}  AND #{endTime})

select ifnull(max(screen_order),0)
from tb_screen_chest_radiograph
where person_id=#{personId} and screen_type=#{screenType};

select *
from tb_screen_chest_radiograph
where person_id=#{personId}

    and screen_order=#{screenOrder}


    and screen_type=#{screenType}

;

select count(case when c.outcome=0 then 1 end) normal,count(case when c.outcome=1 then 1 end) suspected
from tb_screen_chest_radiograph c  join tb_screen_sum s on s.person_id=c.person_id and s.chest_radiograph_num=c.screen_order
where screen_type=#{screenType}

select sc.*,sp.name
from tb_screen_chest_radiograph sc
left join tb_screen_person sp on sc.person_id=sp.id
where sp.screen_point=#{screenPoint}
and sc.year=#{year}
and sc.deleted=0
and sp.deleted=0

    and sc.screen_id like concat('%',#{screenId},'%')


    and sc.outcome=#{outcome}

order by sc.id desc

    limit #{pageNo},#{pageSize}

select ifnull(count(*),0)
from tb_screen_chest_radiograph sc
left join tb_screen_person sp on sc.person_id=sp.id
where sp.screen_point=#{screenPoint}
and sc.year=#{year}
and sc.deleted=0
and sp.deleted=0

    and sc.screen_id like concat('%',#{screenId},'%')


    and sc.outcome=#{outcome}
